using Arconist.Core;
using Arconist.Bridge;
using System.Text.Json;
class Clock:IMonotonicClock{public long Milliseconds{get;set;}}
class Program
{
 static int Main(string[] args){string root=args.Length>0?args[0]:".",output=args.Length>1?args[1]:"arc-bridge-evidence";Directory.CreateDirectory(output);int passed=0,failed=0;var outcomes=new List<object>();
 void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 void Test(string name,Action body){try{body();passed++;outcomes.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception e){failed++;outcomes.Add(new{name,status="FAIL",error=e.ToString()});Console.WriteLine("FAIL "+name+": "+e.Message);}}
 string Load(string name)=>File.ReadAllText(Path.Combine(root,"reconstructed/godot/content",name));
 (Clock,GameplaySession) Start(){var c=new Clock();var s=new GameplaySession(c);s.Start(Load("native_moving_arc.aff"));c.Milliseconds=3002;s.Frame();c.Milliseconds=4002;s.Frame();return(c,s);}
 SkyContact At(GameplaySession s)=>new(new SkyPoint(s.Core!.Arcs[0].TargetX,s.Core.Arcs[0].TargetY,0));
 Test("retained pointer identity and echo guard",()=>{var(c,s)=Start();Check(s.Pointer(100,0,At(s),true),"DOWN");Check(!s.Pointer(100,0,At(s),true)&&!s.Pointer(101,0,At(s),true,true),"duplicates");Check(s.HeldCount==1&&s.Core!.Contacts.Single().Id==0&&s.Core.LastFrameTime==1000,"retention");});
 Test("MOVE retains ID previous location and never judges",()=>{var(c,s)=Start();s.Pointer(100,0,At(s),true);var before=s.Core!.Contacts.Single().Sky;s.MovePointer(100,0,new SkyContact(new SkyPoint(50,300,0)));Check(s.Core.Contacts.Single().Id==0&&s.Core.Contacts.Single().PreviousSky!.Value.Point.X==before!.Value.Point.X&&s.Core.Pure==0&&s.Core.LastFrameTime==1000,"MOVE");});
 Test("pointer UP removes owner and next DOWN fresh ID",()=>{var(c,s)=Start();s.Pointer(100,0,At(s),true);c.Milliseconds++;s.Frame();s.Pointer(100,0,null,false);Check(s.Core!.Arcs[0].Color.Owner==-1&&s.HeldCount==0,"UP");s.Pointer(100,0,At(s),true);Check(s.Core.Contacts.Single().Id==1,"fresh identity");});
 Test("invalid position clears activity while preserving identity",()=>{var(c,s)=Start();s.Pointer(100,0,At(s),true);c.Milliseconds++;s.Frame();s.MovePointer(100,0,null);c.Milliseconds++;s.Frame();Check(!s.Core!.Arcs[0].Holding&&s.Core.ContactCount==1&&s.Core.Arcs[0].Color.Owner==0,"invalid position");});
 Test("pause modal blocks DOWN MOVE; UP delivered",()=>{var(c,s)=Start();s.Pointer(100,0,At(s),true);c.Milliseconds++;s.Frame();s.Pause();Check(!s.Pointer(101,0,At(s),true)&&!s.MovePointer(100,0,At(s)),"modal");Check(s.Pointer(100,0,null,false)&&s.Core!.ContactCount==0&&s.Core.Arcs[0].Color.Owner==-1,"UP during modal");});
 Test("60second arc interruption retains real contact",()=>{var(c,s)=Start();s.Pointer(100,0,At(s),true);c.Milliseconds=4127;s.Frame();c.Milliseconds=4202;s.Pause();c.Milliseconds=64202;s.Frame();Check(s.Core!.Timeline.EffectiveTime==1200&&s.Core.Pure==1&&s.Core.ContactCount==1,"freeze");s.Resume();Check(!s.PauseModalActive,"dismissal");s.MovePointer(100,0,At(s));c.Milliseconds++;s.Frame();Check(s.Core.Arcs[0].Holding&&s.Core.Contacts.Single().Id==0,"reactivate");});
 Test("focus cancellation removes arc ownership without auto resume",()=>{var(c,s)=Start();s.Pointer(100,0,At(s),true);c.Milliseconds++;s.Frame();s.FocusLost();s.FocusReturned();Check(s.Core!.Paused&&s.PauseModalActive&&s.HeldCount==0&&s.Core.ClaimedIds.Count==0&&s.Core.Arcs[0].Color.Owner==-1,"focus policy");s.Resume();Check(s.Pointer(101,0,At(s),true),"new DOWN routing");});
 Test("keyboard ground input has no fabricated sky position",()=>{var(c,s)=Start();s.Key('J',true);c.Milliseconds++;s.Frame();Check(!s.Core!.Arcs[0].Holding&&s.Core.Contacts.Single().Sky==null,"ground independent");s.Pointer(100,0,At(s),true);c.Milliseconds++;s.Frame();Check(s.Core.Arcs[0].Holding&&s.Core.ContactCount==2,"separate pointer");});
 Test("home restart clears ownership contacts modal and checkpoints",()=>{var(c,s)=Start();s.Pointer(100,0,At(s),true);c.Milliseconds=4127;s.Frame();var old=s.Core;s.Pause();s.Home();Check(s.Core==null&&s.HeldCount==0&&!s.PauseModalActive&&old!.Arcs[0].Color.Owner==-1,"home");s.Start(Load("native_moving_arc.aff"));Check(s.Core!.ContactCount==0&&s.Core.Arcs[0].Color.Owner==-1&&s.Core.Pure==0,"fresh run");});
 Test("complete production bridge mixed chart and event identities",()=>{var c=new Clock();var s=new GameplaySession(c);s.Start(Load("sky_practice.aff"));var events=new List<JudgmentEvent>();s.JudgmentsProduced+=e=>events.AddRange(e);c.Milliseconds=3002;s.Frame();for(int e=1;e<=14621;e++){c.Milliseconds=e+3002;var a=s.Core!.Arcs[0];if(e==4000)s.Pointer(100,0,At(s),true);else if(e>4000&&e<=12000)s.MovePointer(100,0,At(s));if(e==12001)s.Pointer(100,0,null,false);foreach(var t in s.Core.Chart.Taps.Where(t=>t.Time==e)){s.Contact(200+t.Ordinal,t.Lane,true);s.Contact(200+t.Ordinal,t.Lane,false);}s.Frame();}Check(s.Core!.Result!.Score==10000035&&events.Count==35&&events.Select(j=>(j.Note,j.CheckpointTime)).Distinct().Count()==35&&s.HeldCount==0,"complete event stream");});
 File.WriteAllText(Path.Combine(output,"bridge-tests.json"),JsonSerializer.Serialize(new{passed,failed,skipped=0,outcomes},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"R007 bridge: {passed+failed}; passed:{passed}; failed:{failed}; skipped:0");return failed==0?0:1;}
}
